@@ -0,0 +1,15 @@
+import { createEventCard, sortEventsByStart } from './event-card.js';
+import { summarizeAttendance } from './attendance.js';
+
+function signupsFor(signupsByEvent, id) {
+  if (signupsByEvent == null || !Object.hasOwn(signupsByEvent, id)) return [];
+  return signupsByEvent[id] ?? [];
+}
+
+export function buildOrganizerDigest(events, signupsByEvent) {
+  return sortEventsByStart(events).map((event) => {
+    const { id, title, dateLabel } = createEventCard(event);
+    const { confirmed, remaining, waitlisted } = summarizeAttendance(event, signupsFor(signupsByEvent, id));
+    return { id, title, dateLabel, confirmed, remaining, waitlisted };
+  });
+}

